import { createPlatformRpcPostHandler } from "../../../../../lib/auth/platform-rpc-route";
import { onboardResultSchema, schoolOnboardingSchema } from "../../../../../lib/platform/customer-contracts";

// Agregar colegio: one transactional command (customer account + colegio + first sede/cafetería).
// Codes are generated by the database from the request key; the browser never supplies them.
export const POST = createPlatformRpcPostHandler({
  capability: "platform:tenant:provision",
  schema: schoolOnboardingSchema,
  resultSchema: onboardResultSchema,
  invoke: (supabase, payload, requestId) => supabase.rpc("platform_onboard_school", {
    p_request_id: requestId, p_school_name: payload.schoolName, p_tax_id: payload.taxId,
    p_address_line: payload.addressLine, p_country_code: payload.countryCode, p_subdivision_code: payload.provinceCode,
  }),
});
